// Только просмотр: ничего не подключается, ссылки не открываются. Две ветки: свободный слот → QR и тексты; 2/2 → сообщение о лимите.
import { by, assert } from '../../lib/appium.mjs';
import { onHome, openTab } from '../../lib/banci.mjs';

export const name = '«מכשירים» → «הוספת טלפון» → «חיבור טלפון נוסף»: QR, «הקוד פעיל 10 דקות», 3 кнопки; при 2/2 — лимит без QR → «סגירה» #e1b6f2 @iphone @app @prod-safe';

export const SHARE_BUTTONS = ['העתקת קישור', 'וואטסאפ', 'הודעה'];
export const LIMIT = 'הגעתם למספר הטלפונים המרבי';

/** «חשבון» → «מכשירים» → «הוספת טלפון». Возвращает 'qr' | 'limit'. */
export async function openAddPhone(app) {
  await onHome(app);
  await openTab(app, 'חשבון');
  const row = await app.scrollTo(by.begins('מכשירים'), { what: 'строка «מכשירים» в «חשבון»' });
  await row.click();
  await app.waitFor(by.contains('הטלפונים בחשבון'), { timeout: 20000, what: 'список «הטלפונים בחשבון»' });
  const add = await app.scrollTo(by.begins('הוספת טלפון'), { max: 4, what: 'кнопка «הוספת טלפון»' });
  await add.click();
  const qrOrLimit = `(${by.contains('קוד QR לחיבור טלפון נוסף')}) OR (${by.contains(LIMIT)})`;
  await app.waitFor(qrOrLimit, { timeout: 15000, what: 'QR «קוד QR לחיבור טלפון נוסף» или сообщение о лимите' });
  return (await app.exists(by.contains(LIMIT))) ? 'limit' : 'qr';
}

export async function closeSheet(app) {
  await app.tap(by.exact('סגירה'), { what: 'кнопка «סגירה»' });
  await app.waitGone(by.contains('חיבור טלפון נוסף'), { what: 'шторка «חיבור טלפון נוסף»' });
  await app.waitFor(by.contains('הטלפונים בחשבון'), { what: 'список «הטלפונים בחשבון» после закрытия' });
}

export default async function (app) {
  const state = await openAddPhone(app);

  if (state === 'qr') {
    // Свободный слот: шторка как в Figma 220-6586 и проверке 01.11.
    await app.waitFor(by.contains('חיבור טלפון נוסף'), { what: 'заголовок «חיבור טלפון נוסף»' });
    await app.waitFor(by.contains('הקוד פעיל 10 דקות'), { what: '«הקוד פעיל 10 דקות»' });
    for (const b of SHARE_BUTTONS) await app.waitFor(by.exact(b), { what: `кнопка «${b}»` });
    assert(!(await app.exists(by.contains(LIMIT))), 'при свободном слоте нет сообщения о лимите');
  } else {
    // 2/2: сообщение о лимите, QR и кнопок шаринга нет.
    console.log('     ветка 2/2: сообщение о лимите');
    assert(!(await app.exists(by.contains('קוד QR לחיבור טלפון נוסף'))), 'при 2/2 QR не показан');
    assert(!(await app.exists(by.contains('הקוד פעיל 10 דקות'))), 'при 2/2 нет «הקוד פעיל 10 דקות»');
    assert(!(await app.exists(by.exact('העתקת קישור'))), 'при 2/2 нет «העתקת קישור»');
  }
  await app.screenshot(`e1b6f2-auto-add-phone-${state}`);

  await closeSheet(app);
  await app.restart();
}
